parameters.jsCode:
const inputData = $input.first().json;

function out(data) { return { json: data }; }

// ---------- INSTAGRAM ----------
if (inputData.object === 'instagram' && inputData.entry && inputData.entry[0]) {
  const entry = inputData.entry[0];
  const pageId = entry.id;

  // DM
  const messaging = entry.messaging ? entry.messaging[0] : null;
  if (messaging && messaging.message && messaging.message.text) {
    return out({
      platform: 'instagram',
      event_type: 'dm',
      pageId,
      senderId: messaging.sender.id,
      senderName: 'Instagram User',
      message: messaging.message.text,
      messageId: messaging.message.mid,
      commentId: null,
      mediaId: null,
      timestamp: messaging.timestamp || Date.now()
    });
  }

  // Comment on a post/ad (requires 'comments' field subscribed in Meta App webhook config)
  const change = entry.changes ? entry.changes[0] : null;
  if (change && change.field === 'comments' && change.value && change.value.text) {
    return out({
      platform: 'instagram',
      event_type: 'comment',
      pageId,
      senderId: (change.value.from && change.value.from.id) || 'unknown',
      senderName: (change.value.from && change.value.from.username) || 'Instagram User',
      message: change.value.text,
      messageId: null,
      commentId: change.value.id,
      mediaId: change.value.media ? change.value.media.id : null,
      timestamp: Date.now()
    });
  }
}

// ---------- FACEBOOK ----------
if (inputData.object === 'page' && inputData.entry && inputData.entry[0]) {
  const entry = inputData.entry[0];
  const pageId = entry.id;

  const messaging = entry.messaging ? entry.messaging[0] : null;
  if (messaging && messaging.message && messaging.message.text) {
    return out({
      platform: 'facebook',
      event_type: 'dm',
      pageId,
      senderId: messaging.sender.id,
      senderName: 'Facebook User',
      message: messaging.message.text,
      messageId: messaging.message.mid,
      commentId: null,
      mediaId: null,
      timestamp: messaging.timestamp
    });
  }

  // Comment on a post/ad (requires 'feed' field subscribed in Meta App webhook config)
  const change = entry.changes ? entry.changes[0] : null;
  if (change && change.field === 'feed' && change.value && change.value.item === 'comment' && change.value.verb === 'add') {
    return out({
      platform: 'facebook',
      event_type: 'comment',
      pageId,
      senderId: (change.value.from && change.value.from.id) || 'unknown',
      senderName: (change.value.from && change.value.from.name) || 'Facebook User',
      message: change.value.message,
      messageId: null,
      commentId: change.value.comment_id,
      mediaId: change.value.post_id,
      timestamp: Date.now()
    });
  }
}

// Unsupported event (delivery/read receipt, reaction, postback, own-page echo) - stop
return null;

