const campaign = $('Merge7').item.json;

// Resolve logo file id: prefer explicit column, else parse from a Drive share URL
function extractDriveFileId(url) {
  if (!url) return '';
  const m1 = url.match(/\/d\/([a-zA-Z0-9_-]+)/);
  if (m1) return m1[1];
  const m2 = url.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  if (m2) return m2[1];
  return '';
}
const logoFileId = campaign.logo_drive_file_id || extractDriveFileId(campaign.logo_url);

// LINK ACCURACY RULE: links/CTA/logo come ONLY from verified company memory,
// never from the LLM. If a link/asset is missing, flag it - never guess one.
const missingLinks = [];
if (!campaign.website_url) missingLinks.push('website_url');
if (!campaign.subscription_link) missingLinks.push('subscription_link');
if (!logoFileId) missingLinks.push('logo_url');

