const taskId = $input.first().json.data.task_id;
if (!taskId) throw new Error('Kling did not return a task ID.');

return [{ json: { taskId, pollAttempt: 0, maxAttempts: 20 } }];

const pollData = $input.first().json;
const data = pollData.data || {};

const rawStatus = (data.task_status || '').toLowerCase();
const taskId = data.task_id || '';
const prevAttempt = pollData.pollAttempt ?? 0;
const maxAttempts = pollData.maxAttempts ?? 20;
const nextAttempt = prevAttempt + 1;

if (rawStatus === 'succeed') {
  const videos = data.task_result && data.task_result.videos;
  const videoUrl = videos && videos[0] ? videos[0].url : null;
  if (!videoUrl) throw new Error('Task succeeded but no video URL found. Raw: ' + JSON.stringify(data));
  return [{ json: { status: 'SUCCEEDED', videoUrl, taskId, pollAttempt: nextAttempt } }];
}

if (rawStatus === 'failed') {
  throw new Error(`Kling task FAILED. Task ID: ${taskId}. Error: ${JSON.stringify(data.task_status_msg || data)}`);
}

if (nextAttempt >= maxAttempts) {
  throw new Error(`Polling timed out after ${maxAttempts} attempts. Task ID: ${taskId}`);
}

return [{ json: { status: 'RUNNING', taskId, pollAttempt: nextAttempt, maxAttempts } }];

